import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export default function ToastExample() {
  return (
    <Button
      onClick={() => {
        toast.add({
          description: "Your changes have been saved.",
          id: "toast-demo-saved",
          title: "Saved",
        });
      }}
    >
      Show toast
    </Button>
  );
}

import ToastExample from "../examples/toast-demo";

const Example = () => (
  <div className="w-full max-w-2xl min-w-72 p-4">
    <ToastExample />
  </div>
);

export default Example;
